    IF cMensaje IS NOT NULL THEN
        OWA_UTIL.MIME_HEADER(''application/json'', FALSE);
        OWA_UTIL.HTTP_HEADER_CLOSE;
        HTP.PRN(''{
                    "success": false,
                    "mensaje": "'' || cMensaje || ''",
                    "data": {}
                }'');
        RETURN;
    END IF;
    -- Ejecuto el servicio para recuperar el catálogo correspondiente
    cResultado := THONAPI.' || 'CATALOGOS_SIGO.ESTRUCTURA_AGENTES( nCodCia     => :nCodCia
                                                           , nCodEmpresa => :nCodEmpresa
                                                           , nCodAgente  => :nCodAgente );
    --
    BEGIN
        cResultado_texto := DBMS_LOB.SUBSTR(cResultado, 32767, 1); 
    EXCEPTION
    WHEN OTHERS THEN
        cResultado_texto := '''';
    END;
    --
    OWA_UTIL.MIME_HEADER(''application/json'', FALSE);    
    OWA_UTIL.HTTP_HEADER_CLOSE;
    --
    IF cResultado_texto IS NULL OR LENGTH(TRIM(cResultado_texto)) < 10 THEN
        HTP.PRN(''{
                    "success": false,
                    "mensaje": "No se encontró una estructura de agentes con los parámetros indicados",
                    "data": []
                }'');
    ELSE
        HTP.PRN(''{
                   "success": true,
                   "mensaje": "",
                   "data": '');
        cResultado := NVL(cResultado, ''{}'');
        ' || 'LOOP
            BEGIN
                DBMS_LOB.READ( cResultado, nIncrementar, nPosicion, cbuffer );
                nPosicion := nPosicion + nIncrementar;
                HTP.PRN(cbuffer);
            EXCEPTION
            WHEN NO_DATA_FOUND THEN
                EXIT;
            END;
        END LOOP;
        --
        HTP.PRN(''}'');
    END IF;
EXCEPTION
WHEN OTHERS THEN
    OWA_UTIL.MIME_HEADER(''application/json'', FALSE);    
        OWA_UTIL.HTTP_HEADER_CLOSE;
        HTP.PRN(''{
                    "success": false,
                    "mensaje": "'' || SQLERRM || ''",
                    "data": []
                }'');
END;');

    
        
COMMIT;

END;